<script setup lang="ts">
import {ref,watch,computed,useId} from 'vue';
import {Dialog,Button,Input,NativeSelect,PageHeader,StatusNotice,useHostContext} from '@openclaw-plugins/control-ui-kit';
import AuthorizationEntityPicker from './AuthorizationEntityPicker.vue';
import {useManagementRequest} from './management-request';
import {actionNames,displayValue,record,array,defaultCategories,categoryRules,ruleSummary,auditSummary,explainReason,type PermissionRow as Row} from './authorization-model';
interface Catalog {agentId:string;mode:string;canAdmin:boolean;actions:string[];groups:Row[];resources:Row[];rules:Row[];bindings:Row[];audit:Row[];policyVersions?:Row[]}
const editFormId=useId();
const props=defineProps<{agentId:string}>(),context=useHostContext(),request=useManagementRequest(context,()=>props.agentId,'agent-repo','authorization-');
const data=ref<Catalog|null>(null),error=ref(''),busy=ref(false),section=ref<'groups'|'resources'|'rules'|'bindings'|'audit'|'simulate'>('groups');
const editing=ref<Row|null>(null),name=ref(''),group=ref('internal'),entity=ref(''),entityType=ref('person'),membership=ref('self'),status=ref('active');
watch(entityType,type=>{membership.value=type==='person'?'self':type==='organization'?'members':['members','descendants'].includes(membership.value)?membership.value:'members';});
const entitySelectionValid=ref(false);
const effect=ref('allow'),ruleKind=ref('explicit'),actions=ref<string[]>([]),resourceIds=ref('');
const conditions=ref<Record<string,string>>({});
const parameterRules=ref('[]');
watch(editing,row=>{parameterRules.value=JSON.stringify(row?.parameters??[],null,2);});
const selectors=ref<Record<string,string>>({});
const selectorLabels:Record<string,string>={kinds:'资源类型',providers:'提供方',labels:'必须具备的分类标签'};
watch(editing,row=>{selectors.value=Object.fromEntries(Object.entries((row?.selector??{}) as Record<string,string[]>).filter(([key])=>key!=='resourceIds').map(([key,values])=>[key,values.join(',')]));});
const conditionLabels:Record<string,string>={destinationHost:'目标域名',destinationOrigin:'目标来源（协议与端口）',protocol:'协议',projectId:'项目',environment:'环境',accountId:'账号',access:'操作性质',atomicity:'原子性',recovery:'可恢复性',idempotency:'幂等性',externalEffect:'外部影响',sensitivity:'数据敏感度'};
interface DefaultPreview {resourceId:string;revision:string;before:unknown[];after:unknown[]}
const defaultPreview=ref<DefaultPreview|null>(null),reviewing=ref<Row|null>(null);
const reviewReady=computed(()=>{const behavior=reviewing.value?.behavior as Record<string,unknown>|undefined;return !!behavior&&['read','write','mixed'].includes(String(behavior.access))&&['none','present'].includes(String(behavior.externalEffect))&&['ordinary','sensitive','restricted'].includes(String(behavior.sensitivity));});
async function confirmReview(){if(!reviewing.value||!canEdit.value||!reviewReady.value)return;const valid=request.capture(),row=reviewing.value;busy.value=true;error.value='';try{await request.invoke('review',{resourceId:row.id,expectedRevision:row.revision,confirmed:true});if(!valid())return;reviewing.value=null;await refresh();}catch(e){if(valid())error.value=String(e);}finally{if(valid())busy.value=false;}}
async function previewDefaults(row:Row){if(!canEdit.value)return;const valid=request.capture();busy.value=true;error.value='';try{const result=await request.invoke<DefaultPreview>('previewDefaults',{resourceId:row.id});if(valid())defaultPreview.value=result;}catch(e){if(valid())error.value=String(e);}finally{if(valid())busy.value=false;}}
async function recomputeDefaults(){if(!defaultPreview.value||!canEdit.value)return;const valid=request.capture();busy.value=true;error.value='';try{await request.invoke('recomputeDefaults',{resourceId:defaultPreview.value.resourceId,expectedRevision:defaultPreview.value.revision});if(!valid())return;defaultPreview.value=null;await refresh();}catch(e){if(valid())error.value=String(e);}finally{if(valid())busy.value=false;}}
const scanSummary=ref('');
const resourceLabels=ref(''),behavior=ref<Record<string,string>>({});
const behaviorChoices:Record<string,string[]>={access:['unknown','read','write','mixed'],atomicity:['unknown','guaranteed','not-guaranteed','not-applicable'],recovery:['unknown','reversible','compensatable','irreversible','not-applicable'],idempotency:['unknown','guaranteed','not-guaranteed','not-applicable'],externalEffect:['unknown','none','present'],sensitivity:['unknown','ordinary','sensitive','restricted']};
const labels:Record<string,string>={groups:'权限组',resources:'资源目录',bindings:'授权对象',audit:'权限记录',simulate:'权限检查'};
const selectedGroup=ref(''),groupTab=ref('explicit'),query=ref(''),kindFilter=ref(''),stateFilter=ref(''),page=ref(1),auditTab=ref('execution');
const selectedGroupRow=computed(()=>data.value?.groups.find(g=>g.id===selectedGroup.value));
const groupRules=computed(()=>(data.value?.rules??[]).filter(r=>r.groupId===selectedGroup.value));
const groupVersions=computed(()=>(data.value?.policyVersions??[]).filter(v=>record(v.rule).groupId===selectedGroup.value));
const draftCount=computed(()=>(data.value?.policyVersions??[]).filter(v=>v.status==='draft').length);
const groupName=(id:unknown)=>data.value?.groups.find(g=>g.id===id)?.name??String(id??'未指定');
const directory=ref<{id:string;name:string;type:string}[]>([]);
const entityName=(id:unknown)=>directory.value.find(e=>e.id===id)?.name??String(id??'未指定');
const rows=computed(()=>{
 let source:Row[]=section.value==='simulate'?[]:data.value?.[section.value]??[];
 if(section.value==='groups'&&selectedGroup.value)source=groupTab.value==='bindings'?(data.value?.bindings??[]).filter(b=>b.groupId===selectedGroup.value):groupTab.value==='history'?groupVersions.value:groupRules.value.filter(r=>r.kind===groupTab.value);
 if(section.value==='rules')source=groupRules.value;
 if(section.value==='audit')source=source.filter(r=>auditTab.value==='execution'?String(r.action).startsWith('execution.')||r.action==='task.scope':!String(r.action).startsWith('execution.')&&r.action!=='task.scope');
 return source.filter(r=>(!kindFilter.value||r.kind===kindFilter.value)&&(!stateFilter.value||r.verification===stateFilter.value||r.enforcement===stateFilter.value||r.status===stateFilter.value)&&(!query.value.trim()||JSON.stringify([r.name,r.id,r.provider,r.labels,r.definition,r.action,r.actor,r.target,r.entityId?entityName(r.entityId):'',r.value]).toLowerCase().includes(query.value.trim().toLowerCase())));
});
const pageRows=computed(()=>rows.value.slice((page.value-1)*20,page.value*20));
const pageCount=computed(()=>Math.max(1,Math.ceil(rows.value.length/20)));
watch([query,kindFilter,stateFilter,section,selectedGroup,groupTab,auditTab],()=>{page.value=1;});
watch(pageCount,n=>{page.value=Math.min(page.value,n);});
function navigate(value:typeof section.value){section.value=value;editing.value=null;query.value='';kindFilter.value='';stateFilter.value='';selectedGroup.value='';}
function openGroup(row:Row,tab='explicit'){selectedGroup.value=row.id;groupTab.value=tab;section.value='groups';editing.value=null;query.value='';}
const editSection=ref('groups');
const modeConfirm=ref(false),publishing=ref<Row|null>(null),detailsRow=ref<Row|null>(null),notice=ref('');
const simulateValid=ref(false),resourceSearch=ref('');
const simulationResources=computed(()=>(data.value?.resources??[]).filter(r=>!resourceSearch.value||[r.name,r.id,r.provider].join(' ').toLowerCase().includes(resourceSearch.value.toLowerCase())));
const simulationResult=computed(()=>record(simulation.value));
const simulationChecks=computed(()=>Array.isArray(simulationResult.value.checks)?simulationResult.value.checks.map(record):[]);
function editIn(kind:string,row?:Row){editSection.value=kind;edit(row);resourceSearch.value='';if(!row&&selectedGroup.value)group.value=selectedGroup.value;if(!row&&kind==='rules')actions.value=['discover','read','execute'];}
function configureCategory(id:string){editIn('rules');applyDefaultPreset(id);}
function rulesForCategory(id:string){return categoryRules(groupRules.value.filter(r=>r.kind==='default'),id);}
function displayOrigin(row:Row){const d=record(row.definition);return [row.provider,d.repository,d.path].filter(Boolean).join(' · ')||row.id;}
function checkResource(row:Row){navigate('simulate');simulateResource.value=row.id;simulateAction.value=row.actions?.includes('execute')?'execute':row.actions?.[0]??'read';}

const simulatePerson=ref(''),simulateResource=ref(''),simulateAction=ref('read'),simulation=ref<unknown>(null);
const simulationContext=ref<Record<string,string>>({}),simulationParameters=ref('{}');
let simulationRevision=0;
watch([simulatePerson,simulateResource,simulateAction,simulationContext,simulationParameters],()=>{simulationRevision++;simulation.value=null;},{deep:true,flush:'sync'});
const simulationFields:Record<string,string>={projectId:'项目',environment:'环境',accountId:'账号',destinationHost:'目标域名',destinationOrigin:'目标来源',protocol:'协议'};
async function simulate(){
 if(!canEdit.value)return;const revision=simulationRevision,valid=request.capture();busy.value=true;error.value='';simulation.value=null;
 try{
  const parameters:unknown=JSON.parse(simulationParameters.value);
  if(parameters===null||typeof parameters!=='object'||Array.isArray(parameters))throw Error('调用参数必须是 JSON 对象');
  if(!simulateValid.value||!simulateResource.value)throw Error('请选择有效人员和目标资源');
  const result=await request.invoke('simulate',{entityId:simulatePerson.value,requirements:[{resourceId:simulateResource.value,action:simulateAction.value}],context:Object.fromEntries(Object.entries(simulationContext.value).filter(([,value])=>value.trim()).map(([key,value])=>[key,value.trim()])),parameters});
  if(valid()&&revision===simulationRevision)simulation.value=result;
 }catch(e){if(valid())error.value=String(e);}finally{if(valid())busy.value=false;}
}
const canEdit=computed(()=>data.value?.canAdmin===true&&!busy.value);
async function refresh(){const valid=request.capture();busy.value=true;error.value='';try{const value=await request.invoke<Catalog>('catalog',{});if(valid()){if(value.agentId!==props.agentId)throw Error('权限资料来源不一致');data.value=value;if(!value.canAdmin){editing.value=null;modeConfirm.value=false;publishing.value=null;detailsRow.value=null;}}}catch(e){if(valid())error.value=String(e);}finally{if(valid())busy.value=false;}}
watch(()=>props.agentId,()=>{data.value=null;editing.value=null;selectedGroup.value='';modeConfirm.value=false;publishing.value=null;detailsRow.value=null;directory.value=[];notice.value='';defaultPreview.value=null;reviewing.value=null;scanSummary.value='';simulation.value=null;simulationContext.value={};simulationParameters.value='{}';simulatePerson.value='';simulateResource.value='';void refresh();},{immediate:true});
function edit(row?:Row){error.value='';entitySelectionValid.value=false;editing.value=row?{...row}:{id:crypto.randomUUID(),revision:0};name.value=String(row?.name??'');group.value=String(row?.groupId??'internal');entity.value=String(row?.entityId??'');entityType.value=String(row?.entityType??'person');membership.value=String(row?.membership??'self');status.value=String(row?.status??'active');effect.value=String(row?.effect??'allow');ruleKind.value=String(row?.kind??'explicit');actions.value=[...(row?.actions??[])];const selector=row?.selector as {resourceIds?:string[]}|undefined;resourceIds.value=selector?.resourceIds?.join(' ')??'';resourceLabels.value=((row?.labels??[]) as string[]).join(',');behavior.value={...((row?.behavior??{}) as Record<string,string>)};conditions.value=Object.fromEntries(Object.entries((row?.conditions??{}) as Record<string,string[]>).map(([key,values])=>[key,values.join(',')]));}
const allActionsSelected=computed(()=>effect.value==='allow_all'||effect.value==='deny_all');
const defaultPresets=defaultCategories;
function applyDefaultPreset(id:string){
 const category=defaultCategories.find(c=>c.id===id);if(!category)return;
 ruleKind.value='default';effect.value='allow';
 actions.value=id==='read'?['discover','read','execute']:['discover','execute','create','update','delete'];
 conditions.value=Object.fromEntries(Object.entries({...category.conditions,sensitivity:['ordinary'],externalEffect:['none']}).map(([key,value])=>[key,value.join(',')]));
}
function editGroupDefaults(row:Row){openGroup(row,'default');}
async function save(){if(!editing.value||!canEdit.value)return;const valid=request.capture(),row=editing.value;let value:Record<string,unknown>;
 if(editSection.value==='bindings'&&!entitySelectionValid.value){error.value='请从下拉列表选择有效实体';return;}
 if(editSection.value==='rules'&&!allActionsSelected.value&&!actions.value.length){error.value='请至少选择一种操作权限';return;}
 if(editSection.value==='rules')try{const parameters:unknown=JSON.parse(parameterRules.value);if(!Array.isArray(parameters))throw Error('参数约束必须是数组');row.parameters=parameters;}catch(e){error.value=String(e);return;}
 if(editSection.value==='resources'){busy.value=true;try{await request.invoke('classify',{resourceId:row.id,expectedRevision:row.revision,labels:resourceLabels.value.split(',').map(v=>v.trim()).filter(Boolean),behavior:behavior.value});if(!valid())return;editing.value=null;notice.value='资源分类已保存';await refresh();}catch(e){if(valid())error.value=String(e);}finally{if(valid())busy.value=false;}return;}
 if(editSection.value==='groups')value={...row,name:name.value,status:status.value};
 else if(editSection.value==='bindings')value={...row,groupId:group.value,entityId:entity.value,entityType:entityType.value,membership:entityType.value==='person'?'self':entityType.value==='organization'?'members':membership.value,status:status.value};
 else {const ids=resourceIds.value.split(/\s+/).filter(Boolean);value={...row,groupId:group.value,kind:ruleKind.value,effect:effect.value,actions:allActionsSelected.value?[]:actions.value,selector:{...Object.fromEntries(Object.entries(selectors.value).filter(([,value])=>value.trim()).map(([key,value])=>[key,value.split(',').map(item=>item.trim()).filter(Boolean)])),...(ids.length?{resourceIds:ids}:{})},conditions:Object.fromEntries(Object.entries(conditions.value).filter(([,value])=>value.trim()).map(([key,value])=>[key,value.split(',').map(item=>item.trim()).filter(Boolean)]))};}
 busy.value=true;error.value='';try{await request.invoke('save',{kind:editSection.value,value,expectedRevision:row.revision});if(!valid())return;editing.value=null;if(editSection.value==='rules'){selectedGroup.value=group.value;section.value='groups';groupTab.value='history';}notice.value=editSection.value==='rules'?'草稿已保存，请在权限组的变更记录中核对并发布。':'保存成功，配置已生效。';await refresh();}catch(e){if(valid())error.value=String(e);}finally{if(valid())busy.value=false;}}
async function publish(row:Row){if(!canEdit.value)return;const valid=request.capture();busy.value=true;error.value='';try{await request.invoke('publish',{id:row.id,expectedRevision:row.revision});if(valid()){publishing.value=null;modeConfirm.value=false;await refresh();}}catch(e){if(valid())error.value=String(e);}finally{if(valid())busy.value=false;}}
async function scan(){if(!canEdit.value)return;const valid=request.capture();busy.value=true;error.value='';try{const result=await request.invoke<{discovered:number;changed:number;complete:boolean;failures:Array<{scope:string;reason:string}>}>('scan',{});if(!valid())return;scanSummary.value=`发现 ${result.discovered} 项，变化 ${result.changed} 项。`+(result.complete?'扫描完成。':'部分范围未完成：'+result.failures.map(item=>item.scope+' '+item.reason).join('；'));await refresh();}catch(e){if(valid())error.value=String(e);}finally{if(valid())busy.value=false;}}
async function mode(){if(!data.value||!canEdit.value)return;const valid=request.capture();busy.value=true;error.value='';try{await request.invoke('mode',{mode:data.value.mode==='audit'?'enforce':'audit'});if(valid()){publishing.value=null;modeConfirm.value=false;await refresh();}}catch(e){if(valid())error.value=String(e);}finally{if(valid())busy.value=false;}}

watch([section,()=>data.value?.canAdmin],async()=>{if(!data.value?.canAdmin||!['bindings','groups','audit'].includes(section.value)||directory.value.length)return;const valid=request.capture();try{const result=await request.invoke<{agentId:string;entities:{id:string;name:string;type:string}[]}>('entityOptions',{});if(valid()&&result.agentId===props.agentId)directory.value=Array.isArray(result.entities)?result.entities:[];}catch{/* IDs remain visible if directory lookup fails. */}});
</script>
<template>
 <section class="ar-authorization">
  <PageHeader title="权限中心" description="通过权限组管理组织、部门和个人交给 Worker 执行的能力；Main 沿用 OpenClaw 权限。"/>
  <StatusNotice v-if="error" tone="error">{{error}}</StatusNotice>
  <StatusNotice v-if="notice" tone="info" role="status">{{notice}}</StatusNotice>
  <div v-if="data" class="mode-bar"><strong>Worker · {{data.mode==='audit'?'仅记录，不拦截':'强制拦截'}}</strong><span>{{draftCount}} 项未发布修改</span><details><summary>控制覆盖说明</summary><p>仅控制已接入鉴权的 Worker 调用，Main 沿用 OpenClaw 权限。原生 Shell、文件、网络及未接入能力沿用执行环境配置，权限组不提供完整沙箱隔离。</p></details><Button v-if="data.canAdmin" variant="outline" :disabled="busy" @click="modeConfirm=true">{{data.mode==='audit'?'启用强制拦截':'切换为审计'}}</Button></div>
  <nav aria-label="权限管理分类"><Button v-for="(label,key) in labels" :key="key" variant="ghost" :aria-current="section===key?'page':undefined" @click="navigate(key as typeof section)">{{label}}</Button><Button variant="outline" :disabled="busy" @click="refresh">刷新</Button></nav>
  <template v-if="section==='groups'&&selectedGroupRow">
   <div class="toolbar"><Button variant="outline" @click="selectedGroup=''">返回权限组</Button><h3>{{selectedGroupRow.name}}</h3><span class="badge">{{displayValue(selectedGroupRow.status)}}</span></div>
   <p>{{selectedGroupRow.description}}</p>
   <nav aria-label="权限组详情"><Button v-for="(label,key) in {explicit:'资源权限',default:'新增资源默认权限',bindings:'绑定对象',history:'变更记录'}" :key="key" variant="ghost" :aria-current="groupTab===key?'page':undefined" @click="groupTab=key;editing=null;query=''">{{label}} {{key==='history'?groupVersions.filter(v=>v.status==='draft').length:''}}</Button></nav>
   <p v-if="groupTab==='explicit'">未单独授权时沿用该资源已形成的默认授权；没有匹配允许则拒绝。任一匹配的明确禁止优先。</p>
   <template v-if="groupTab==='default'">
    <p>默认策略用于后续接入、核验或分类更新的资源；发布修改不会自动改写已有授权。存量资源请从资源目录预览后逐项应用。</p>
    <div class="table-wrap"><table><caption>新增资源默认权限分类</caption><thead><tr><th>操作类别</th><th>相关已发布规则</th><th>配置</th></tr></thead><tbody><tr v-for="category in defaultPresets" :key="category.id"><th>{{category.label}}</th><td>{{rulesForCategory(category.id).length?rulesForCategory(category.id).length+' 条相关规则，具体以资源范围和条件为准':'不自动授权'}}</td><td><Button v-if="canEdit" variant="outline" @click="configureCategory(category.id)">配置{{category.label}}</Button></td></tr></tbody></table></div>
    <p class="muted">原子性不等于可撤销；可撤销不代表自动回滚。模板限普通数据、无外部副作用的操作。未知属性、未核验、未接入拦截及宽泛执行能力不能据此自动放行。现有自定义规则保留在下方，不会被模板覆盖。</p>
   </template>
  </template>
  <div v-if="section!=='simulate'" class="toolbar">
   <Input v-model="query" aria-label="搜索当前列表" placeholder="搜索名称、来源、标签或标识"/>
   <template v-if="section==='resources'"><NativeSelect v-model="kindFilter" aria-label="资源类型筛选"><option value="">所有类型</option><option v-for="kind in [...new Set(data?.resources.map(r=>r.kind).filter(Boolean))]" :key="kind" :value="kind">{{displayValue(kind)}}</option></NativeSelect><NativeSelect v-model="stateFilter" aria-label="资源状态筛选"><option value="">所有状态</option><option value="pending">待核验</option><option value="verified">已核验</option><option value="enforced">已接入拦截</option></NativeSelect><Button v-if="canEdit" @click="scan">扫描当前能力</Button></template>
   <Button v-if="canEdit&&section==='groups'&&!selectedGroup" @click="editIn('groups')">新增权限组</Button>
   <Button v-if="canEdit&&((section==='groups'&&selectedGroup&&['explicit','default'].includes(groupTab)))" @click="editIn('rules');ruleKind=groupTab">新增规则</Button>
   <Button v-if="canEdit&&(section==='bindings'||section==='groups'&&selectedGroup&&groupTab==='bindings')" @click="editIn('bindings')">新增实体绑定</Button>
  </div>
  <p v-if="section==='resources'&&scanSummary" role="status">{{scanSummary}}</p>
  <p v-if="section==='groups'&&!selectedGroup">先配置权限组，再绑定组织、部门或个人。预置组名称不代表绕过明确禁止或执行边界。</p>
  <p v-if="section==='bindings'">保存绑定立即生效；组织和部门按已核验关系参与权限计算。个人绑定不会覆盖其他组的明确禁止。</p>
  <Dialog :open="!!editing" :session-scoped="false" size="detail" :title="editSection==='groups'?'编辑权限组':editSection==='bindings'?'绑定授权对象':editSection==='resources'?'编辑资源分类':'编辑权限规则'" :prevent-close="busy" @update:open="value=>{if(!value)editing=null}"><form v-if="editing" :id="editFormId" @submit.prevent="save"><StatusNotice v-if="error" tone="error">{{error}}</StatusNotice>
   <template v-if="editSection==='groups'"><label>名称<Input v-model="name" required/></label><p>保存后立即生效；组名称不会直接授予任何资源权限。</p></template>
   <template v-else-if="editSection!=='resources'"><label>权限组<NativeSelect v-model="group"><option v-for="g in data?.groups" :key="g.id" :value="g.id">{{g.name}}</option></NativeSelect></label></template>
   <template v-if="editSection==='resources'"><label>分类标签（逗号分隔）<Input v-model="resourceLabels"/></label><label v-for="(choices,key) in behaviorChoices" :key="key">{{conditionLabels[key]}}<NativeSelect v-model="behavior[key]"><option v-for="choice in choices" :key="choice" :value="choice">{{displayValue(choice)}}</option></NativeSelect></label><p>分类修改不等于核验；通用工具需核验后执行，专用适配器保持自身约束。</p></template>
   <template v-if="editSection==='bindings'"><label>实体类型<NativeSelect v-model="entityType"><option value="person">个人</option><option value="department">部门</option><option value="organization">组织</option></NativeSelect></label><AuthorizationEntityPicker :key="String(editing.id)" v-model="entity" :agent-id="agentId" :entity-type="entityType" :disabled="!canEdit" @validity="entitySelectionValid=$event"/><label v-if="entityType==='department'">覆盖范围<NativeSelect v-model="membership"><option value="members">直属成员</option><option value="descendants">包含下级部门</option></NativeSelect></label></template>
   <template v-if="editSection==='rules'"><label>策略类型<NativeSelect v-model="ruleKind"><option value="explicit">已有资源授权</option><option value="default">新增资源默认授权</option></NativeSelect></label><fieldset v-if="ruleKind==='default'"><legend>默认授权模板</legend><Button v-for="preset in defaultPresets" :key="preset.id" type="button" variant="outline" @click="applyDefaultPreset(preset.id)">{{preset.label}}</Button><p>模板仅允许普通数据且无外部副作用的操作。未匹配的写入与未知资源不自动授权；同时满足原子性与可撤销性可选组合模板。条件可在下方调整。</p></fieldset><label>效果<NativeSelect v-model="effect"><option value="allow">允许</option><option value="deny">明确禁止</option><option value="allow_all">全部授权</option><option value="deny_all">全部拒绝</option></NativeSelect></label><p v-if="allActionsSelected">覆盖所选资源和条件内的全部操作。多个权限组同时命中时，拒绝优先。</p><details v-else :open="ruleKind==='explicit'"><summary>操作权限</summary><fieldset><legend>权限类型</legend><label v-for="action in data?.actions" :key="action"><input type="checkbox" v-model="actions" :value="action">{{actionNames[action]??action}}</label></fieldset></details><label>搜索可选资源<Input v-model="resourceSearch" placeholder="名称、提供方或标识"/></label><label>选择资源<NativeSelect aria-label="添加授权资源" model-value="" @update:model-value="resourceIds=[...new Set([...resourceIds.split(/\s+/).filter(Boolean),String($event)])].join(' ')"><option value="">选择并添加资源</option><option v-for="r in simulationResources" :key="r.id" :value="r.id">{{r.name??r.id}} · {{displayValue(r.kind)}} · {{displayOrigin(r)}}</option></NativeSelect></label><p>已选资源：{{resourceIds?resourceIds.split(/\s+/).map(id=>data?.resources.find(r=>r.id===id)?.name??id).join('、'):'全部资源（可用分类标签进一步限制）'}}</p><details><summary>手动编辑资源标识</summary><label>资源 ID（空格分隔；留空匹配全部资源）<Input v-model="resourceIds"/></label></details><details><summary>高级条件</summary><fieldset><legend>授权条件（多个允许值用逗号分隔）</legend><label v-for="(label,key) in conditionLabels" :key="key">{{label}}<Input v-model="conditions[key]"/></label></fieldset></details></template>
   <label v-else-if="editSection!=='resources'">状态<NativeSelect v-model="status"><option value="active">启用</option><option value="disabled">停用</option></NativeSelect></label>
   <template v-if="editSection==='rules'"><fieldset><legend>资源范围（多值用逗号分隔）</legend><label v-for="(label,key) in selectorLabels" :key="key">{{label}}<Input v-model="selectors[key]" :aria-label="label"/></label><p>不同条件同时满足；分类标签要求全部具备。留空不限制该条件。</p></fieldset><details><summary>高级参数约束</summary><label>参数约束（高级配置）<textarea v-model="parameterRules" aria-label="参数约束" rows="5"/></label><p>每项填写 path、op、value，所有约束必须同时满足。例如 [{"path":"limit","op":"max","value":100}] 限制单次数量。支持 equals、in、subset、present、max、min；空数组表示不限制参数。</p></details></template>
   <StatusNotice v-if="editSection==='bindings'" tone="info">将 {{entityName(entity)}} 绑定到 {{groupName(group)}}。覆盖{{entityType==='person'?'此人':entityType==='organization'?'组织成员':membership==='descendants'?'当前及下级部门成员':'直属成员'}}；保存后立即生效。</StatusNotice><p v-if="editSection==='rules'">当前条件：{{Object.entries(conditions).filter(([,value])=>value).map(([key,value])=>(conditionLabels[key]??key)+'：'+value.split(',').map(displayValue).join(' / ')).join('；')||'无额外条件'}}。保存只生成草稿；请在该权限组的变更记录中发布。明确禁止会覆盖其他允许规则。</p></form><template #footer><Button type="submit" :form="editFormId" :disabled="!canEdit||(editSection==='bindings'&&!entitySelectionValid)">{{editSection==='rules'?'保存草稿':'保存'}}</Button><Button type="button" variant="outline" @click="editing=null">取消</Button></template></Dialog>

  <StatusNotice v-if="section==='simulate'&&!data?.canAdmin" tone="info">权限检查需要管理员权限。</StatusNotice><form v-if="section==='simulate'&&data?.canAdmin" @submit.prevent="simulate"><AuthorizationEntityPicker v-model="simulatePerson" :agent-id="agentId" entity-type="person" :disabled="!canEdit" @validity="simulateValid=$event"/><label>搜索资源<Input v-model="resourceSearch" placeholder="名称、提供方或标识"/></label><label>目标资源<NativeSelect v-model="simulateResource" required><option value="" disabled>选择资源</option><option v-for="r in simulationResources" :key="r.id" :value="r.id">{{r.name??r.id}} · {{displayValue(r.kind)}} · {{displayOrigin(r)}}</option></NativeSelect></label><label>权限类型<NativeSelect v-model="simulateAction"><option v-for="a in data?.actions" :key="a" :value="a">{{actionNames[a]??a}}</option></NativeSelect></label><fieldset><legend>模拟执行上下文</legend><label v-for="(label,key) in simulationFields" :key="key">{{label}}<Input v-model="simulationContext[key]" :aria-label="'模拟'+label"/></label></fieldset><label>调用参数（JSON 对象）<textarea v-model="simulationParameters" aria-label="模拟调用参数" rows="5"/></label><p>这里只验证指定资源操作，不执行业务调用；模拟值不会替代真实执行时的可信上下文。</p><Button type="submit" :disabled="!canEdit||!simulateValid||!simulateResource">检查有效权限</Button><section v-if="simulation" aria-label="权限检查结果"><h3>策略判定：{{simulationResult.allowed?'允许':'拒绝'}}</h3><p>{{explainReason(simulationResult.reason)}}</p><p>实际模式：{{data?.mode==='audit'?'仅记录，此策略判定不会触发拦截':'强制拦截，仅适用于已接入的调用'}}。检查不执行业务，也不包含真实任务的权限快照。</p><article v-for="(check,index) in simulationChecks" :key="index"><strong>{{check.resourceId}} · {{actionNames[String(check.action)]??check.action}}</strong><p>{{explainReason(check.reason)}}</p><p>命中规则：{{array(check.ruleIds).join('、')||'无'}}</p></article><p>绑定依据：{{array(simulationResult.bindingIds).map(id=>{const binding=data?.bindings.find(b=>b.id===id);return binding?entityName(binding.entityId)+' → '+groupName(binding.groupId)+'（'+(binding.entityType==='person'?'个人直接绑定':binding.entityType==='organization'?'组织继承':'部门继承')+'）':id}).join('；')||'无'}}</p><details><summary>技术详情</summary><pre>{{JSON.stringify(simulation,null,2)}}</pre></details></section></form>
  <section v-if="reviewing&&section==='resources'" aria-label="工具分类核验"><h3>核验工具分类</h3><p>请核对当前定义和分类是否覆盖该工具全部行为。确认后应用权限组的新增资源默认策略。原子性、可撤销性由管理员依据实现核验；通用拦截控制调用入口，不提供沙箱或自动回滚。</p><pre>{{JSON.stringify({id:reviewing.id,definition:reviewing.definition,behavior:reviewing.behavior},null,2)}}</pre><p v-if="!reviewReady">请先编辑资源，明确操作性质、外部影响和数据敏感度。</p><Button :disabled="!canEdit||!reviewReady" @click="confirmReview">确认分类并启用</Button><Button variant="outline" @click="reviewing=null">取消核验</Button></section>
  <section v-if="defaultPreview&&section==='resources'" aria-label="默认授权变更预览"><h3>默认授权变更预览</h3><p>{{defaultPreview.resourceId}}</p><pre>{{JSON.stringify({before:defaultPreview.before,after:defaultPreview.after},null,2)}}</pre><Button :disabled="!canEdit" @click="recomputeDefaults">应用此授权变更</Button><Button variant="outline" @click="defaultPreview=null">取消</Button></section>

  <nav v-if="section==='audit'" aria-label="权限记录类型"><Button variant="ghost" :aria-current="auditTab==='execution'?'page':undefined" @click="auditTab='execution'">调用判定</Button><Button variant="ghost" :aria-current="auditTab==='changes'?'page':undefined" @click="auditTab='changes'">配置变更</Button><span class="muted">最近 {{data?.audit.length??0}} 条保留记录中的结果</span></nav>
  <div v-if="section!=='simulate'" class="table-wrap" tabindex="0" aria-label="权限列表，可横向滚动"><table><caption>{{selectedGroupRow?.name??labels[section]}} · {{rows.length}} 条</caption><thead><tr><th>对象</th><th>状态与范围</th><th>说明</th><th>操作</th></tr></thead><tbody>
   <tr v-for="row in pageRows" :key="row.id">
    <td><template v-if="section==='audit'"><strong>{{auditSummary(row).title}}</strong><small>{{auditSummary(row).at}}</small></template><template v-else-if="section==='bindings'||section==='groups'&&selectedGroup&&groupTab==='bindings'"><strong>{{entityName(row.entityId)}}</strong><small>{{{person:'个人',department:'部门',organization:'组织'}[String(row.entityType)]}} · {{groupName(row.groupId)}}</small></template><template v-else-if="section==='groups'&&selectedGroup&&groupTab==='history'"><strong>{{displayValue(row.status)}} · 规则变更</strong><small>{{row.createdAt?new Date(String(row.createdAt)).toLocaleString():'时间未提供'}}</small></template><template v-else><strong>{{row.name??(row.effect?displayValue(row.effect)+'规则':row.id)}}</strong><small v-if="section==='resources'">{{displayValue(row.kind)}} · {{displayOrigin(row)}}</small><span v-if="row.builtin" class="badge">预置组</span></template></td>
    <td><template v-if="section==='resources'"><span class="badge">{{displayValue(row.verification??'unknown')}}</span><span class="badge">{{row.enforcement==='enforced'?'已接入拦截':'尚未接入拦截'}}</span><small>资源状态：{{displayValue(row.status)}}</small><small>{{displayValue(record(row.behavior).access??'unknown')}} · 原子性 {{displayValue(record(row.behavior).atomicity??'unknown')}} · 恢复 {{displayValue(record(row.behavior).recovery??'unknown')}}</small></template><template v-else-if="section==='audit'">{{auditSummary(row).result}}<small>{{auditSummary(row).reason}}</small></template><template v-else-if="row.entityId">{{displayValue(row.status)}} · {{row.membership==='self'?'仅本人':row.membership==='descendants'?'含下级部门成员':'直属/组织成员'}}</template><template v-else-if="section==='groups'&&!selectedGroup">{{displayValue(row.status)}}<small>{{data?.bindings.filter(b=>b.groupId===row.id&&b.status==='active').length}} 个启用绑定 · {{data?.rules.filter(r=>r.groupId===row.id).length}} 条已发布规则</small><small>{{data?.policyVersions?.filter(v=>v.status==='draft'&&record(v.rule).groupId===row.id).length??0}} 项待发布</small></template><template v-else>{{row.kind==='default'?'新增资源默认授权':row.kind==='explicit'?'已有资源授权':displayValue(row.status)}}</template></td>
    <td><template v-if="section==='audit'">操作者：{{entityName(row.actor)}}<small>对象：{{row.target}}</small></template><template v-else-if="row.effect">{{ruleSummary(row)}}</template><template v-else-if="section==='groups'&&groupTab==='history'&&selectedGroup">{{ruleSummary(record(row.rule) as unknown as Row)}}</template><template v-else-if="section==='resources'"><span v-for="tag in array(row.labels)" :key="tag" class="badge">{{tag}}</span><small v-if="row.defaultAuthorization==='explicit-only'">宽泛执行：仅支持显式授权，不提供沙箱隔离。</small></template><template v-else>{{row.description??'通过权限检查查看最终判定；明确禁止优先。'}}</template></td>
    <td><div class="row-actions"><Button variant="ghost" @click="detailsRow=row">详情</Button><template v-if="section==='groups'&&!selectedGroup"><Button variant="outline" @click="openGroup(row)">管理权限</Button><Button v-if="canEdit" variant="ghost" @click="editIn('groups',row)">编辑</Button><Button variant="ghost" @click="editGroupDefaults(row)">配置新增资源默认授权</Button></template><template v-else-if="section==='resources'"><Button v-if="canEdit" variant="ghost" @click="editIn('resources',row)">编辑</Button><Button v-if="canEdit&&row.reviewEligible" variant="ghost" @click="reviewing=row">核验并启用</Button><Button v-if="canEdit" variant="ghost" @click="previewDefaults(row)">预览默认授权</Button><Button v-if="canEdit" variant="ghost" @click="checkResource(row)">检查权限</Button></template><template v-else-if="section==='bindings'||section==='groups'&&groupTab==='bindings'"><Button v-if="canEdit" variant="ghost" @click="editIn('bindings',row)">编辑</Button></template><template v-else-if="row.effect"><Button v-if="canEdit" variant="ghost" @click="editIn('rules',row)">编辑</Button></template><Button v-if="canEdit&&row.status==='draft'" variant="outline" @click="publishing=row">核对并发布</Button></div></td>
   </tr>
  </tbody></table><p v-if="!rows.length" class="empty">{{busy?'正在读取…':query||kindFilter||stateFilter?'没有匹配结果，请调整筛选条件。':'暂无记录。可以从上方入口开始配置。'}}</p></div>
  <div v-if="section!=='simulate'&&rows.length" class="toolbar pagination"><span>共 {{rows.length}} 条 · 第 {{page}} / {{pageCount}} 页</span><Button variant="outline" :disabled="page<=1" @click="page--">上一页</Button><Button variant="outline" :disabled="page>=pageCount" @click="page++">下一页</Button></div>
  <Dialog :open="modeConfirm" :session-scoped="false" title="确认运行模式变更" size="detail" :prevent-close="busy" @update:open="modeConfirm=$event"><p>当前为{{data?.mode==='audit'?'仅记录':'强制拦截'}}。切换后只影响已接入鉴权的 Worker 调用，Main 不受影响。</p><p>{{data?.bindings.filter(b=>b.status==='active').length??0}} 个启用绑定，{{data?.resources.filter(r=>r.verification!=='verified').length??0}} 项资源未核验，{{data?.resources.filter(r=>r.enforcement!=='enforced').length??0}} 项未接入拦截。</p><p>未绑定成员的精确人数及未来调用影响暂无法计算；请先检查关键人员和资源的有效权限。正在执行的任务仍受自身权限快照约束。</p><StatusNotice v-if="error" tone="error">{{error}}</StatusNotice><template #footer><Button variant="outline" :disabled="busy" @click="modeConfirm=false">取消</Button><Button :disabled="!canEdit" @click="mode">确认切换模式</Button></template></Dialog>
  <Dialog :open="!!publishing" :session-scoped="false" title="核对并发布规则" size="detail" :prevent-close="busy" @update:open="value=>{if(!value)publishing=null}"><template v-if="publishing"><p>权限组：{{groupName(record(publishing.rule).groupId)}}</p><h4>发布前</h4><p>{{publishing.before?ruleSummary(record(publishing.before) as unknown as Row):'无此规则'}}</p><h4>发布后</h4><p>{{ruleSummary(record(publishing.rule) as unknown as Row)}}</p><p>该组有 {{data?.bindings.filter(b=>b.groupId===record(publishing?.rule).groupId&&b.status==='active').length}} 个启用绑定。实际受影响人数及调用数未计算。</p><p>{{record(publishing.rule).kind==='default'?'仅更改后续资源默认授权；存量授权需单独预览并应用。':'发布后参与权限判定，明确禁止优先。'}}</p><details><summary>完整变更（含参数约束）</summary><pre>{{JSON.stringify({before:publishing.before,after:publishing.rule},null,2)}}</pre></details><StatusNotice v-if="error" tone="error">{{error}}</StatusNotice></template><template #footer><Button variant="outline" :disabled="busy" @click="publishing=null">取消</Button><Button :disabled="!canEdit" @click="publishing&&publish(publishing)">发布此规则</Button></template></Dialog>
  <Dialog :open="!!detailsRow" :session-scoped="false" title="详情与判定依据" size="detail" @update:open="value=>{if(!value)detailsRow=null}"><p v-if="detailsRow?.effect">{{ruleSummary(detailsRow)}}</p><pre>{{JSON.stringify(detailsRow,null,2)}}</pre></Dialog>

 </section>
</template>
<style scoped>
.ar-authorization{min-width:0;container-type:inline-size}.ar-authorization nav,.toolbar,.mode-bar,.row-actions{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.ar-authorization nav{margin:16px 0;border-bottom:1px solid var(--ocp-border);padding-bottom:8px}.ar-authorization nav [aria-current=page]{background:var(--ocp-secondary);box-shadow:inset 0 -2px var(--ocp-primary);font-weight:600}.mode-bar{padding:12px 16px;border:1px solid var(--ocp-border);border-radius:8px}.mode-bar details{flex:1;min-width:160px}.mode-bar p{max-width:720px}.toolbar{margin:16px 0}.toolbar>input{flex:1;min-width:180px;max-width:400px}.toolbar>select{max-width:190px}.table-wrap{max-width:100%;overflow:auto;border:1px solid var(--ocp-border);border-radius:8px}table{width:100%;border-collapse:collapse;font-size:13px;table-layout:fixed;min-width:660px}caption{text-align:left;padding:12px 16px;color:var(--ocp-muted)}th,td{padding:12px 16px;text-align:left;vertical-align:top;border-bottom:1px solid var(--ocp-border);overflow-wrap:anywhere}thead th{background:var(--ocp-secondary);font-weight:500}th:first-child{width:23%}th:last-child{width:23%}td small{display:block;margin-top:6px;color:var(--ocp-muted)}.badge{display:inline-block;padding:2px 7px;background:var(--ocp-secondary);border:1px solid var(--ocp-border);border-radius:4px;font-size:12px;margin:2px}.row-actions{gap:4px}.row-actions button{font-size:12px}.empty{padding:24px;text-align:center}.pagination{justify-content:flex-end}.pagination>span{margin-right:auto}.muted{color:var(--ocp-muted);font-size:13px}form{display:grid;gap:16px;min-width:0}form>label,label{display:grid;gap:6px;min-width:0}fieldset{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;min-width:0;border:1px solid var(--ocp-border);padding:12px;border-radius:6px}fieldset label:has(input[type=checkbox]){display:flex;align-items:center}fieldset p{grid-column:1/-1}textarea{width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--ocp-border);border-radius:6px;background:var(--ocp-background);color:inherit}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}article{padding:12px;border-bottom:1px solid var(--ocp-border)}summary{cursor:pointer}section>form{max-width:800px}h3{margin:0}p{line-height:1.6}@container(max-width:600px){.toolbar>input{max-width:none}.mode-bar{align-items:flex-start}.mode-bar details{flex-basis:100%}}
</style>
